# Let's try to manually figure out what transformations work
inputs = ['vzc', 'gdyzdv', 'hj', 'zzek', 'kxj']
outputs = ['vzc', 'gdvgezdv', 'hj', 'zzek', 'kikbj']

print("Examining each transformation:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input: '{inp}' -> Output: '{out}'")

print("\nChecking for simple substitutions:")
# Let's check what characters change
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"\nTransformation {i}: '{inp}' -> '{out}'")
        # Find differences
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        if len(inp) != len(out):
            print(f"  Length changed: {len(inp)} -> {len(out)}")

